package com.peiwan.platform.order;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.peiwan.platform.payment.OrderPaymentService;import com.peiwan.platform.settlement.SettlementService;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class OrderService{
 private final OrderMapper orders;private final OrderItemMapper items;private final OrderGameProfileMapper profiles;private final OrderStatusLogMapper logs;private final OrderDataMapper data;private final PlayerMapper players;private final ObjectMapper json;private final OrderPaymentService paymentService;private final SettlementService settlementService;
 public OrderService(OrderMapper orders,OrderItemMapper items,OrderGameProfileMapper profiles,OrderStatusLogMapper logs,OrderDataMapper data,PlayerMapper players,ObjectMapper json,OrderPaymentService paymentService,SettlementService settlementService){this.orders=orders;this.items=items;this.profiles=profiles;this.logs=logs;this.data=data;this.players=players;this.json=json;this.paymentService=paymentService;this.settlementService=settlementService;}
 public Map<String,Object> list(int current,int size,String orderNo,String customerName,String status){current=Math.max(1,current);size=Math.min(200,Math.max(1,size));var result=data.orders(new Page<>(current,size),s(orderNo),s(customerName),status);return Map.of("records",result.getRecords().stream().map(this::orderView).toList(),"current",current,"size",size,"total",result.getTotal());}
 public Map<String,Object> detail(long id){var row=data.orderDetail(id);if(row==null)throw new IllegalArgumentException("订单不存在");var order=orderView(row);order.put("items",items.selectList(new QueryWrapper<OrderItemEntity>().eq("order_id",id).orderByAsc("id")).stream().map(this::itemView).toList());var profile=profiles.selectOne(new QueryWrapper<OrderGameProfileEntity>().eq("order_id",id));order.put("gameProfile",profile==null?null:profileView(profile));order.put("statusLogs",data.statusLogs(id).stream().map(this::logView).toList());return order;}
 public List<Map<String,Object>> customers(){return data.customers().stream().map(r->map("id",r.get("id"),"label",Objects.toString(r.get("nickname"),Objects.toString(r.get("username"))),"username",r.get("username"),"phone",r.get("phone"))).toList();}
 public List<Map<String,Object>> players(){return data.players().stream().map(r->map("id",r.get("id"),"label",r.get("nickname"),"playerNo",r.get("player_no"))).toList();}
 @Transactional public long create(CreateCommand c,long operator){if(c.customerId()==null)throw new IllegalArgumentException("请选择下单用户");if(c.skuId()==null)throw new IllegalArgumentException("请选择销售规格");if(c.quantity()<1)throw new IllegalArgumentException("购买数量必须大于0");var customer=data.enabledCustomer(c.customerId());if(customer==null)throw new IllegalArgumentException("下单用户不存在或已禁用");var sku=data.skuSnapshot(c.skuId());if(sku==null)throw new IllegalArgumentException("销售规格不存在");if(!"ON_SALE".equals(sku.get("product_status"))||!Boolean.TRUE.equals(sku.get("enabled")))throw new IllegalArgumentException("商品或销售规格未上架");int min=((Number)sku.get("min_quantity")).intValue();Integer max=sku.get("max_quantity")==null?null:((Number)sku.get("max_quantity")).intValue();if(c.quantity()<min||max!=null&&c.quantity()>max)throw new IllegalArgumentException("购买数量不符合规格限制");if("LIMITED".equals(sku.get("stock_mode"))&&data.decrementStock(c.skuId(),c.quantity())==0)throw new IllegalArgumentException("库存不足");var unit=(BigDecimal)sku.get("price");var total=unit.multiply(BigDecimal.valueOf(c.quantity()));var o=new OrderEntity();o.orderNo=orderNo();o.customerId=c.customerId();o.orderStatus="PENDING_PAYMENT";o.totalAmount=total;o.payableAmount=total;o.paidAmount=BigDecimal.ZERO;o.contactName=blank(c.contactName(),Objects.toString(customer.get("nickname"),Objects.toString(customer.get("username"))));o.contactPhone=blank(c.contactPhone(),Objects.toString(customer.get("phone"),""));o.customerRemark=c.customerRemark();o.createdBy=operator;orders.insert(o);var item=new OrderItemEntity();item.orderId=o.id;item.productId=((Number)sku.get("product_id")).longValue();item.skuId=c.skuId();item.productCode=(String)sku.get("product_code");item.productName=(String)sku.get("product_name");item.skuCode=(String)sku.get("sku_code");item.skuName=(String)sku.get("sku_name");item.productType=(String)sku.get("product_type");item.unitPrice=unit;item.quantity=c.quantity();item.subtotalAmount=total;item.serviceSnapshot=serviceSnapshot(item.productId);items.insert(item);var profile=new OrderGameProfileEntity();profile.orderId=o.id;profile.gameId=((Number)sku.get("game_id")).longValue();profile.gameName=(String)sku.get("game_name");profile.gameAccount=c.gameAccount();profile.gameNickname=c.gameNickname();profile.serverName=c.serverName();profile.rankName=c.rankName();profile.extraRequirement=c.extraRequirement();profiles.insert(profile);log(o.id,null,"PENDING_PAYMENT",operator,"创建订单");return o.id;}
 @Transactional public void changeStatus(long id,String target,String reason,long operator){var o=requireOrder(id);String from=o.orderStatus;var allowed=Map.of("PENDING_PAYMENT",Set.of("CANCELLED"),"WAIT_ASSIGN",Set.of("CANCELLED"),"ASSIGNED",Set.of("IN_SERVICE","CANCELLED"),"IN_SERVICE",Set.of("COMPLETED"));if(!allowed.getOrDefault(from,Set.of()).contains(target))throw new IllegalArgumentException("订单不能从"+from+"变更为"+target);o.orderStatus=target;o.updatedAt=LocalDateTime.now();if("IN_SERVICE".equals(target))o.serviceStartedAt=LocalDateTime.now();else if("COMPLETED".equals(target))o.completedAt=LocalDateTime.now();else{paymentService.refundOrder(id,operator,reason);o.paidAmount=BigDecimal.ZERO;o.cancelReason=reason;o.cancelledAt=LocalDateTime.now();restoreStock(id);}orders.updateById(o);if("COMPLETED".equals(target))settlementService.settleOrder(id);if(("COMPLETED".equals(target)||"CANCELLED".equals(target))&&o.assignedPlayerId!=null&&data.activePlayerOrders(o.assignedPlayerId)==0){var p=players.selectById(o.assignedPlayerId);if(p!=null){p.workStatus="AVAILABLE";p.updatedAt=LocalDateTime.now();players.updateById(p);}}log(id,from,target,operator,reason);}
 @Transactional public void cancelOwn(long uid,long id,String reason){var o=orders.selectOne(new QueryWrapper<OrderEntity>().eq("id",id).eq("customer_id",uid));if(o==null)throw new IllegalArgumentException("订单不存在或不属于当前用户");if(!Set.of("PENDING_PAYMENT","WAIT_ASSIGN").contains(o.orderStatus))throw new IllegalArgumentException("当前订单不能取消");changeStatus(id,"CANCELLED",reason,uid);}
 @Transactional public void assign(long id,long playerId,String reason,long operator){var o=requireOrder(id);String from=o.orderStatus;if(!"WAIT_ASSIGN".equals(from))throw new IllegalArgumentException("只有待派单订单可以分配陪玩师");var p=players.selectById(playerId);if(p==null||!Boolean.TRUE.equals(p.enabled)||!"APPROVED".equals(p.auditStatus))throw new IllegalArgumentException("陪玩师不存在、未启用或未通过审核");o.assignedPlayerId=playerId;o.orderStatus="ASSIGNED";o.assignedAt=LocalDateTime.now();o.updatedAt=LocalDateTime.now();orders.updateById(o);log(id,from,"ASSIGNED",operator,reason);}
 private void restoreStock(long id){for(var r:data.stockRows(id))if("LIMITED".equals(r.get("stock_mode")))data.restoreStock(((Number)r.get("sku_id")).longValue(),((Number)r.get("quantity")).intValue());}
 private String serviceSnapshot(long productId){try{return json.writeValueAsString(data.serviceSnapshot(productId));}catch(JsonProcessingException e){throw new IllegalArgumentException("商品服务快照生成失败");}}
 private void log(long id,String from,String to,long operator,String reason){var l=new OrderStatusLogEntity();l.orderId=id;l.fromStatus=from;l.toStatus=to;l.operatorId=operator;l.reason=reason;logs.insert(l);}
 private OrderEntity requireOrder(long id){var x=orders.selectById(id);if(x==null)throw new IllegalArgumentException("订单不存在");return x;}
 private Map<String,Object> orderView(Map<String,Object>r){return view(r,new String[][]{{"id","id"},{"orderNo","order_no"},{"customerId","customer_id"},{"customerUsername","customer_username"},{"customerNickname","customer_nickname"},{"assignedPlayerId","assigned_player_id"},{"playerName","player_name"},{"productName","product_name"},{"orderStatus","order_status"},{"totalAmount","total_amount"},{"payableAmount","payable_amount"},{"paidAmount","paid_amount"},{"contactName","contact_name"},{"contactPhone","contact_phone"},{"customerRemark","customer_remark"},{"cancelReason","cancel_reason"},{"paidAt","paid_at"},{"assignedAt","assigned_at"},{"serviceStartedAt","service_started_at"},{"completedAt","completed_at"},{"cancelledAt","cancelled_at"},{"createTime","created_at"}});}private Map<String,Object> itemView(OrderItemEntity r){return map("id",r.id,"productId",r.productId,"skuId",r.skuId,"productCode",r.productCode,"productName",r.productName,"skuCode",r.skuCode,"skuName",r.skuName,"productType",r.productType,"unitPrice",r.unitPrice,"quantity",r.quantity,"subtotalAmount",r.subtotalAmount,"serviceSnapshot",r.serviceSnapshot);}private Map<String,Object> profileView(OrderGameProfileEntity r){return map("gameId",r.gameId,"gameName",r.gameName,"gameAccount",r.gameAccount,"gameNickname",r.gameNickname,"serverName",r.serverName,"rankName",r.rankName,"extraRequirement",r.extraRequirement);}private Map<String,Object> logView(Map<String,Object>r){return view(r,new String[][]{{"id","id"},{"fromStatus","from_status"},{"toStatus","to_status"},{"operatorId","operator_id"},{"operatorName","operator_name"},{"reason","reason"},{"createTime","created_at"}});}private Map<String,Object> view(Map<String,Object>r,String[][]keys){var out=new LinkedHashMap<String,Object>();for(var k:keys)if(r.containsKey(k[1]))out.put(k[0],r.get(k[1]));return out;}
 private Map<String,Object> map(Object...v){var m=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}private String orderNo(){return "ORD"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();}private String s(String v){return Objects.toString(v,"");}private String blank(String v,String d){return v==null||v.isBlank()?d:v;}public record CreateCommand(Long customerId,Long skuId,int quantity,String contactName,String contactPhone,String customerRemark,String gameAccount,String gameNickname,String serverName,String rankName,String extraRequirement){}
}
